// Built-in pixel-art farm animal starter pack. Each file in
// web/public/sprites/pack/<id>-strip.png is a 384x64 transparent PNG
// containing six 64x64 frames (stand, walk 1, walk 2, sick, lying down, happy),
// generated by web/scripts/gen-starter-pack.py.

export const STARTER_PACK_IDS = [
  'donkey',
  'duck',
  'goose',
  'turkey',
  'rabbit',
  'alpaca',
  'rooster',
  'mouse',
] as const;

export type StarterPackId = (typeof STARTER_PACK_IDS)[number];

export interface StarterPackAnimal {
  readonly id: StarterPackId;
  readonly labelKey: `kid.farm.picture.pack.${StarterPackId}`;
  readonly stripUrl: `/sprites/pack/${StarterPackId}-strip.png`;
  readonly frames: 6;
}

export const STARTER_PACK: readonly StarterPackAnimal[] = STARTER_PACK_IDS.map((id) => ({
  id,
  labelKey: `kid.farm.picture.pack.${id}`,
  stripUrl: `/sprites/pack/${id}-strip.png`,
  frames: 6,
}));
